INSERT INTO words (word_id, word, phonetic, part_of_speech, definitions_json, analysis_json, collocation, examples_json, word_family_json, secondary_meaning_note, difficulty, frequency_rank, toeic_rank) VALUES
(6500, 'tender submission', '/ˈtendər səbˈmɪʃən/', 'noun', '{"zh-TW":["投標提交"],"en":["the formal process of submitting a bid for a project or contract"]}', NULL, 'prepare a tender submission / tender submission deadline', '[{"en":"The tender submission was completed and submitted before the deadline.","zh-TW":"投標提交在截止日期前完成並提交。"},{"en":"Tender submissions must include full pricing and technical details.","zh-TW":"投標提交必須包括完整的定價和技術細節。"}]', NULL, NULL, 5, 6500, NULL),
(6501, 'tenders', '/ˈtendərz/', 'noun', '{"zh-TW":["投標書；招標"],"en":["formal offers to provide goods or services at a stated price"]}', NULL, 'submit tenders / invite tenders / evaluate tenders', '[{"en":"Three companies submitted tenders for the construction contract.","zh-TW":"三家公司提交了建築合約的投標書。"},{"en":"The lowest tender was accepted after quality assessment.","zh-TW":"在品質評估後接受了最低的投標書。"}]', '{"singular":"tender","verb":"tender"}', NULL, 3, 6501, NULL),
(6502, 'tentative', '/ˈtentətɪv/', 'adjective', '{"zh-TW":["暫定的；試探性的"],"en":["not certain or fixed; provisional"]}', NULL, 'tentative agreement / tentative plan / tentative schedule', '[{"en":"We reached a tentative agreement on pricing.","zh-TW":"我們就定價達成了暫定協議。"},{"en":"The tentative launch date is in March.","zh-TW":"暫定的上市日期在三月。"}]', '{"adjective":"tentative","adverb":"tentatively"}', NULL, 3, 6502, NULL),
(6503, 'tenuous', '/ˈtenjuəs/', 'adjective', '{"zh-TW":["薄弱的；不充分的"],"en":["very weak or slight; lacking substance"]}', NULL, 'tenuous connection / tenuous argument / tenuous link', '[{"en":"The evidence for this claim is tenuous at best.","zh-TW":"這一主張的證據充其量是薄弱的。"},{"en":"His argument rests on a tenuous assumption that rarely holds.","zh-TW":"他的論點依賴一個鮮少成立的薄弱假設。"}]', '{"adverb":"tenuously","noun":"tenuousness"}', NULL, 3, 6503, NULL),
(6504, 'tenure', '/ˈtenjər/', 'noun', '{"zh-TW":["任期；任職期間"],"en":["the holding of an office or position"]}', NULL, 'during one''s tenure / job tenure / tenure track', '[{"en":"During her tenure, revenue doubled.","zh-TW":"在她任職期間，營收翻倍。"},{"en":"Average employee tenure at the company is five years.","zh-TW":"員工在公司的平均任期是五年。"}]', '{"noun":"tenure","adjective":"tenured"}', NULL, 2, 6504, NULL),
(6505, 'term', 'tɜːrm', 'noun', '{"zh-TW":["【主要意義-名詞】術語；學期","【次要意義-動詞】稱呼；稱為","【次要意義-名詞】任期；任職期間","【次要意義-複數名詞】條款；條件；協議內容"],"en":["[primary - noun] a word or expression; a fixed period of time","[secondary - verb] to give a name or label to something","[secondary - noun] a period of office or service","[secondary - plural noun] the conditions of an agreement"]}', NULL, 'in terms of / terms and conditions / come to terms / term of office', '[{"en":"The agreement terms must be reviewed before signing the contract.","zh-TW":"在簽署合約之前必須審查協議條款。"},{"en":"In terms of profitability, this has been our best year.","zh-TW":"就盈利能力而言，這是我們最好的一年。"},{"en":"She served a full term as director before retiring.","zh-TW":"她在退休前完整擔任了一個任期的董事。"}]', '{"adjective":"terminal, long-term, short-term"}', 'terms（複數）= 「條款/條件」是 TOEIC 合約類文章的必考詞，in terms of（就……而言）是高頻搭配，動詞 term = 「稱呼/稱為」也常見於正式文章。', 1, 6505, NULL),
(6506, 'term deposit', '/tɜːrm dɪˈpɒzɪt/', 'noun', '{"zh-TW":["定期存款"],"en":["a fixed-term savings account with a fixed interest rate"]}', NULL, 'open a term deposit / term deposit rate', '[{"en":"The company placed surplus funds in a six-month term deposit.","zh-TW":"公司將盈餘資金存入六個月期的定期存款。"},{"en":"Term deposit rates vary depending on the deposit amount and duration.","zh-TW":"定期存款利率根據存款金額和期限而有所不同。"}]', '{"synonym":"certificate of deposit"}', NULL, 4, 6506, NULL),
(6507, 'term loan', '/tɜːrm loʊn/', 'noun', '{"zh-TW":["定期貸款"],"en":["a loan that is repaid over a fixed period with scheduled payments"]}', NULL, 'arrange a term loan / term loan repayment', '[{"en":"The company took a five-year term loan to finance the factory expansion.","zh-TW":"公司獲得了五年定期貸款以資助工廠擴張。"},{"en":"Term loan interest rates can be fixed or variable.","zh-TW":"定期貸款利率可以是固定或浮動的。"}]', NULL, NULL, 3, 6507, NULL),
(6508, 'term sheet', '/tɜːrm ʃiːt/', 'noun', '{"zh-TW":["條款清單；意向書"],"en":["a non-binding document outlining key terms of a proposed deal"]}', NULL, 'issue a term sheet / review the term sheet', '[{"en":"The VC firm issued a term sheet for a 10 million dollar investment.","zh-TW":"風險投資公司就1000萬元投資出具了條款清單。"},{"en":"Both parties agreed to the term sheet before drafting the final contract.","zh-TW":"雙方在起草最終合約前同意了條款清單。"}]', NULL, NULL, 4, 6508, NULL),
(6509, 'terminal', '/ˈtɜːrmɪnəl/', 'noun', '{"zh-TW":["航站樓；終點站"],"en":["a building at an airport where passengers arrive and depart"]}', NULL, 'international terminal / airport terminal', '[{"en":"Flight 302 departs from Terminal B.","zh-TW":"302號航班從B航站樓出發。"},{"en":"The new terminal has more shopping options.","zh-TW":"新航站樓有更多購物選擇。"}]', '{"adjective":"terminal"}', NULL, 3, 6509, NULL),
(6510, 'terminate', '/ˈtɜːrmɪneɪt/', 'verb', '{"zh-TW":["終止；結束"],"en":["to bring to an end"]}', NULL, 'terminate a contract / terminate employment / terminate an agreement', '[{"en":"Either party may terminate the contract with 30 days'' notice.","zh-TW":"任何一方均可提前30天通知終止合約。"},{"en":"His employment was terminated due to misconduct.","zh-TW":"他因不當行為而被解雇。"}]', '{"noun":"termination","verb":"terminate"}', NULL, 3, 6510, 65),
(6511, 'termination', '/ˌtɜːrmɪˈneɪʃən/', 'noun', '{"zh-TW":["解僱；終止"],"en":["the ending of an employee''s contract by the employer"]}', NULL, 'termination letter / wrongful termination / contract termination', '[{"en":"The termination was effective immediately.","zh-TW":"解僱即刻生效。"},{"en":"She filed a lawsuit claiming wrongful termination.","zh-TW":"她提起訴訟，聲稱被不當解僱。"}]', '{"verb":"terminate","adjective":"terminated"}', NULL, 4, 6511, 626),
(6512, 'terms and conditions', '/tɜːrmz ənd kənˈdɪʃənz/', 'noun', '{"zh-TW":["條款與條件"],"en":["the stipulations governing the rights and obligations in an agreement"]}', NULL, 'review terms and conditions / accept terms and conditions', '[{"en":"Customers must read the terms and conditions before creating an account.","zh-TW":"客戶在創建帳戶前必須閱讀條款與條件。"},{"en":"The terms and conditions specify the refund and cancellation policies.","zh-TW":"條款與條件規定了退款和取消政策。"}]', '{"abbreviation":"T&C"}', NULL, 5, 6512, NULL),
(6513, 'terms of payment', '/tɜːrmz əv ˈpeɪmənt/', 'noun', '{"zh-TW":["付款條件"],"en":["the agreed conditions for when and how payment is made"]}', NULL, 'negotiate terms of payment / standard terms of payment', '[{"en":"Standard terms of payment are net 30 days.","zh-TW":"標準的付款條件是30天內付清。"},{"en":"The supplier requested different terms of payment for large orders.","zh-TW":"供應商要求大訂單採用不同的付款條件。"}]', NULL, NULL, 5, 6513, NULL),
(6514, 'terms of trade', '/tɜːrmz əv treɪd/', 'noun', '{"zh-TW":["貿易條件"],"en":["the ratio of a country''s export prices to its import prices"]}', NULL, 'improve terms of trade / deteriorating terms of trade / favorable terms of trade', '[{"en":"Rising commodity prices improved the terms of trade for natural resource-exporting nations.","zh-TW":"商品價格上漲改善了自然資源出口國的貿易條件。"},{"en":"Developing countries with deteriorating terms of trade face structural current account deficits.","zh-TW":"貿易條件惡化的發展中國家面臨結構性經常賬戶赤字。"}]', NULL, NULL, 5, 6514, NULL),
(6515, 'terrain', '/''tɜːreɪn/', 'noun', '{"zh-TW":["地形；地勢"],"en":["a stretch of land, especially with regard to its physical features"]}', NULL, 'rough terrain / mountainous terrain / navigate terrain', '[{"en":"The off-road vehicle was designed to handle rugged terrain.","zh-TW":"這輛越野車的設計用於應對崎嶇地形。"},{"en":"Hikers need proper footwear to tackle uneven terrain safely.","zh-TW":"徒步者需要合適的鞋子才能安全應對不平坦的地形。"}]', NULL, NULL, 3, 6515, NULL),
(6516, 'territory', '/ˈterɪtɔːri/', 'noun', '{"zh-TW":["領土；區域","銷售區域"],"en":["an area of land; a region assigned to someone"]}', NULL, 'sales territory / expand into new territory / uncharted territory', '[{"en":"The sales rep covers the entire eastern territory.","zh-TW":"這位銷售代表負責整個東部區域。"},{"en":"We are expanding into new territory in Southeast Asia.","zh-TW":"我們正在東南亞拓展新領域。"}]', '{"noun":"territory","adjective":"territorial"}', NULL, 3, 6516, NULL),
(6517, 'testify', '/ˈtestɪfaɪ/', 'verb', '{"zh-TW":["作證；證明"],"en":["to give evidence as a witness"]}', NULL, 'testify in court / testify against / testify to', '[{"en":"The accountant testified in the fraud case.","zh-TW":"會計師在詐欺案中作證。"},{"en":"The results testify to the success of the program.","zh-TW":"結果證明了該計畫的成功。"}]', '{"noun":"testimony, testimonial","verb":"testify"}', NULL, 3, 6517, NULL),
(6518, 'testimonial', '/ˌtɛstɪˈməʊniəl/', 'noun', '{"zh-TW":["客戶評價；推薦信"],"en":["a written or spoken statement endorsing a product or person"]}', NULL, 'customer testimonial / positive testimonial', '[{"en":"Customer testimonials can greatly influence buying decisions.","zh-TW":"客戶評價可以極大地影響購買決策。"},{"en":"The website features testimonials from satisfied clients.","zh-TW":"網站上展示了滿意顧客的評價。"}]', NULL, NULL, 4, 6518, NULL),
(6519, 'testimony', '/ˈtɛstɪmoʊni/', 'noun', '{"zh-TW":["證詞"],"en":["a formal statement given in court"]}', NULL, 'give testimony / expert testimony', '[{"en":"Her testimony was crucial to the case.","zh-TW":"她的證詞對案件至關重要。"},{"en":"He gave testimony before Congress.","zh-TW":"他在國會前作證。"}]', '{"verb":"testify"}', NULL, 3, 6519, NULL),
(6520, 'textbook', '/ˈtɛkstbʊk/', 'noun', '{"zh-TW":["教科書"],"en":["a book used for studying a subject"]}', NULL, 'textbook example / buy textbooks', '[{"en":"Textbooks are expensive.","zh-TW":"教科書很貴。"},{"en":"This is a textbook example of good design.","zh-TW":"這是好設計的典型範例。"}]', NULL, NULL, 3, 6520, NULL),
(6521, 'texture', '/''tekstʃər/', 'noun', '{"zh-TW":["質地；口感"],"en":["the feel, consistency, and appearance of a substance, especially food"]}', NULL, 'crunchy texture / smooth texture / improve texture', '[{"en":"The avocado added a creamy texture to the salad dressing.","zh-TW":"牛油果為沙拉醬增添了奶油般的質地。"},{"en":"Baking with almond flour changes the texture of cookies compared to regular flour.","zh-TW":"使用杏仁粉烘焙會改變餅乾的質地，與普通麵粉相比有所不同。"}]', NULL, NULL, 3, 6521, NULL),
(6522, 'theater', '/ˈθiːətər/', 'noun', '{"zh-TW":["劇院；戲劇"],"en":["a building for performances","the art of writing and performing plays"]}', '{"root":{"text":"thea","meaning":"view (觀看)"},"suffix":{"text":"-ter","meaning":"place (場所)"},"logic":"觀看表演的場所，即「劇院」。"}', 'movie theater / theater performance', '[{"en":"We saw a play at the local theater.","zh-TW":"我們在當地劇院看了一場戲。"},{"en":"She studied theater in college.","zh-TW":"她在大學主修戲劇。"}]', '{"adjective":"theatrical"}', NULL, 3, 6522, NULL),
(6523, 'theoretical', '/ˌθɪəˈretɪkəl/', 'adjective', '{"zh-TW":["理論的；理論上的"],"en":["concerned with theories rather than their practical application"]}', NULL, 'theoretical framework / theoretical basis / theoretical model', '[{"en":"The paper lays out a theoretical framework for analysis.","zh-TW":"論文為分析奠定了一個理論框架。"},{"en":"Theoretical knowledge must eventually be tested in practice.","zh-TW":"理論知識最終必須在實踐中加以驗證。"}]', '{"adverb":"theoretically","noun":"theory"}', NULL, 4, 6523, NULL),
(6524, 'therapy', '/ˈθɛrəpi/', 'noun', '{"zh-TW":["治療；療法"],"en":["treatment for a physical or mental condition"]}', NULL, 'physical therapy / therapy session', '[{"en":"Physical therapy was recommended after the knee surgery.","zh-TW":"膝蓋手術後建議進行物理治療。"},{"en":"She attends therapy sessions every week to manage stress.","zh-TW":"她每週參加療法課程來管理壓力。"}]', '{"verb":"treat","noun":"therapist","adjective":"therapeutic"}', NULL, 3, 6524, NULL),
(6525, 'thesis', '/ˈθiːsɪs/', 'noun', '{"zh-TW":["論文；論點"],"en":["a long essay for a degree","a theory to be proved","a long piece of writing for a degree"]}', NULL, 'master''s thesis / central thesis; master''s thesis / thesis statement', '[{"en":"Her master''s thesis focused on supply chain efficiency.","zh-TW":"她的碩士論文專注於供應鏈效率。"},{"en":"The central thesis of the report is cost reduction.","zh-TW":"報告的核心論點是成本削減。"},{"en":"She''s writing her master''s thesis.","zh-TW":"她正在寫碩士論文。"},{"en":"Your thesis statement should be clear.","zh-TW":"你的論點應該要清楚。"}]', '{"noun":"thesis","plural":"theses"}', NULL, 2, 6525, NULL),
(6526, 'thesis advisor', '/''θiːsɪs ədˌvaɪzər/', 'noun', '{"zh-TW":["論文指導教授；論文顧問"],"en":["a professor who supervises and guides a graduate student''s thesis research"]}', NULL, 'work with a thesis advisor / find a thesis advisor / thesis advisor feedback', '[{"en":"Her thesis advisor provided invaluable guidance throughout the research process.","zh-TW":"她的論文指導教授在整個研究過程中提供了寶貴的指導。"},{"en":"Choosing the right thesis advisor is crucial for graduate school success.","zh-TW":"選擇合適的論文指導教授對研究生院的成功至關重要。"}]', NULL, NULL, 5, 6526, NULL),
(6527, 'thesis statement', '/''θiːsɪs ˌsteɪtmənt/', 'noun', '{"zh-TW":["論點陳述；論文中心論點"],"en":["a statement in an essay or research paper that describes the main argument or point"]}', NULL, 'develop a thesis statement / strong thesis statement / clear thesis statement', '[{"en":"A clear thesis statement gives the reader a roadmap for the entire essay.","zh-TW":"清晰的論點陳述為讀者提供了整篇文章的路線圖。"},{"en":"Her thesis statement concisely captured the main argument of her research paper.","zh-TW":"她的論點陳述簡潔地捕捉了研究論文的主要論點。"}]', '{"noun":"thesis"}', NULL, 5, 6527, NULL),
(6528, 'thin capitalization', '/θɪn ˌkæpɪtəlaɪˈzeɪʃən/', 'noun', '{"zh-TW":["薄資本化；資本不足"],"en":["a situation where a company is financed with a high proportion of debt relative to equity"]}', NULL, 'thin capitalization rules / address thin capitalization / thin capitalization scheme', '[{"en":"Tax authorities use thin capitalization rules to prevent profit shifting through excessive debt.","zh-TW":"稅務機關使用薄資本化規則，以防止通過過度負債轉移利潤。"},{"en":"A highly leveraged subsidiary with thin capitalization may raise regulatory concerns.","zh-TW":"資本嚴重不足的高度槓桿子公司可能會引發監管方面的擔憂。"}]', NULL, NULL, 5, 6528, NULL),
(6529, 'think', 'θɪŋk', 'verb', '{"zh-TW":["思考；認為","考慮"],"en":["to use your mind","to hold an opinion"]}', NULL, 'think about/of/outside the box', '[{"en":"Think carefully before making a decision.","zh-TW":"做決定前要仔細思考。"}]', '{"noun":"thought, thinker","adjective":"thoughtful","adverb":"thoughtfully"}', NULL, 2, 6529, NULL),
(6530, 'third party', '/θɜːrd ˈpɑːrti/', 'noun', '{"zh-TW":["第三方"],"en":["an external organization or person not directly involved in a transaction"]}', NULL, 'third-party audit / third-party verification / involve a third party', '[{"en":"A third party was brought in to independently verify the results.","zh-TW":"引入了第三方對結果進行獨立核實。"},{"en":"The contract requires all disputes to be resolved through a third party.","zh-TW":"合約要求所有爭議通過第三方解決。"}]', '{"adjective":"third-party"}', NULL, 4, 6530, NULL),
(6531, 'third-party auditor', '/θɜːrd ˈpɑːrti ˈɔːdɪtər/', 'noun', '{"zh-TW":["第三方審計師"],"en":["an independent party hired to assess the accuracy of accounts or compliance"]}', NULL, 'engage a third-party auditor / third-party auditor report', '[{"en":"A third-party auditor confirmed the financial statements were accurate.","zh-TW":"第三方審計師確認了財務報表的準確性。"},{"en":"Hiring a third-party auditor builds credibility with investors.","zh-TW":"聘用第三方審計師建立了與投資者的信譽。"}]', NULL, NULL, 5, 6531, NULL),
(6532, 'third-party logistics', '/θɜːrd pɑːrti ləˈdʒɪstɪks/', 'noun', '{"zh-TW":["第三方物流"],"en":["outsourcing logistics operations to an external service provider"]}', NULL, 'hire third-party logistics / third-party logistics provider', '[{"en":"The retailer outsourced delivery to a third-party logistics company.","zh-TW":"零售商將配送外包給第三方物流公司。"},{"en":"Third-party logistics providers offer warehousing and distribution services.","zh-TW":"第三方物流提供商提供倉儲和配送服務。"}]', '{"abbreviation":"3PL"}', NULL, 5, 6532, NULL),
(6533, 'third-party vendor', '/θɜːrd ˈpɑːrti ˈvendər/', 'noun', '{"zh-TW":["第三方供應商"],"en":["an external supplier that provides goods or services to a business"]}', NULL, 'select a third-party vendor / third-party vendor agreement', '[{"en":"The IT department evaluated five third-party vendors for the new software.","zh-TW":"IT部門評估了五家第三方供應商以選擇新軟件。"},{"en":"Third-party vendors must adhere to the company''s quality and security standards.","zh-TW":"第三方供應商必須遵守公司的品質和安全標準。"}]', NULL, NULL, 5, 6533, NULL),
(6534, 'thorough', '/ˈθʌroʊ/', 'adjective', '{"zh-TW":["徹底的；詳盡的"],"en":["complete with attention to every detail"]}', NULL, 'thorough investigation / thorough review / thorough analysis', '[{"en":"We conducted a thorough investigation.","zh-TW":"我們進行了徹底的調查。"},{"en":"The report requires a more thorough analysis.","zh-TW":"這份報告需要更詳盡的分析。"}]', '{"adjective":"thorough","adverb":"thoroughly","noun":"thoroughness"}', NULL, 3, 6534, NULL),
(6535, 'thought leadership', '/θɔːt ˈliːdərʃɪp/', 'noun', '{"zh-TW":["思想領袖；意見領袖地位"],"en":["being recognized as an expert and influencing others in a field"]}', NULL, 'establish thought leadership / thought leadership content / thought leadership strategy', '[{"en":"Publishing white papers helped the firm build thought leadership.","zh-TW":"發布白皮書幫助公司建立了思想領袖地位。"},{"en":"Thought leadership attracts both customers and top talent.","zh-TW":"思想領袖地位吸引了客戶和頂尖人才。"}]', '{"noun":"thought leader"}', NULL, 5, 6535, NULL),
(6536, 'thought-provoking', '/''θɔːt prəˌvəʊkɪŋ/', 'adjective', '{"zh-TW":["發人深省的；引人思考的"],"en":["stimulating careful consideration or attention; making you think deeply"]}', NULL, 'thought-provoking question / thought-provoking discussion / thought-provoking book', '[{"en":"The documentary raised thought-provoking questions about the future of artificial intelligence.","zh-TW":"這部紀錄片提出了關於人工智能未來的發人深省的問題。"},{"en":"A thought-provoking seminar can transform the way students see a familiar topic.","zh-TW":"一場發人深省的研討會可以改變學生看待熟悉話題的方式。"}]', '{"verb":"provoke thought"}', NULL, 5, 6536, NULL),
(6537, 'thousand', 'ˈθaʊzənd', 'noun', '{"zh-TW":["千；一千","大量"],"en":["the number 1,000","a large round number"]}', NULL, 'a thousand/thousands of', '[{"en":"Thousands of customers visit our site daily.","zh-TW":"每天有數千名客戶訪問我們的網站。"}]', '{"adjective":"thousand","adverb":"thousandfold"}', NULL, 3, 6537, NULL),
(6538, 'threat', '/θret/', 'noun', '{"zh-TW":["威脅；恐嚇"],"en":["a statement of intention to harm; a danger"]}', NULL, 'pose a threat / security threat / under threat', '[{"en":"Cybersecurity threats are increasing globally.","zh-TW":"全球網路安全威脅正在增加。"},{"en":"Climate change poses a serious threat to businesses.","zh-TW":"氣候變遷對企業構成嚴重威脅。"}]', '{"noun":"threat","verb":"threaten","adjective":"threatening"}', NULL, 2, 6538, NULL),
(6539, 'three-course meal', '/θriː kɔːrs miːl/', 'noun', '{"zh-TW":["三道菜餐"],"en":["a meal consisting of starter, main course, and dessert"]}', NULL, 'enjoy a three-course meal / three-course meal deal', '[{"en":"The anniversary dinner included a romantic three-course meal.","zh-TW":"週年紀念晚餐包含了浪漫的三道菜大餐。"},{"en":"A three-course meal at this restaurant costs 60 dollars.","zh-TW":"這家餐廳的三道菜套餐售價60元。"}]', NULL, NULL, 5, 6539, NULL),
(6540, 'threshold', '/ˈθreʃhoʊld/', 'noun', '{"zh-TW":["門檻；起始點"],"en":["the level at which something starts"]}', NULL, 'tax threshold / below the threshold / pain threshold', '[{"en":"Income below the threshold is tax-free.","zh-TW":"低於門檻的收入免稅。"},{"en":"The company has reached the profitability threshold.","zh-TW":"公司已達到盈利門檻。"}]', '{"noun":"threshold"}', NULL, 3, 6540, 941),
(6541, 'thrive', '/θraɪv/', 'verb', '{"zh-TW":["蓬勃發展；興旺"],"en":["to grow or develop well"]}', NULL, 'thrive in / thrive on / thriving business', '[{"en":"Small businesses thrived during the digital boom.","zh-TW":"小型企業在數位化潮流中蓬勃發展。"},{"en":"She thrives under pressure.","zh-TW":"她在壓力下表現出色。"}]', '{"verb":"thrive","adjective":"thriving"}', NULL, 2, 6541, NULL),
(6542, 'throughput', '/ˈθruːpʊt/', 'noun', '{"zh-TW":["吞吐量；產出率"],"en":["the rate at which goods or transactions are processed"]}', NULL, 'increase throughput / production throughput / maximize throughput', '[{"en":"Removing the bottleneck increased the assembly line''s throughput.","zh-TW":"消除瓶頸增加了裝配線的吞吐量。"},{"en":"The port''s throughput capacity was expanded to handle more vessels.","zh-TW":"港口的吞吐能力被擴大以處理更多船隻。"}]', NULL, NULL, 4, 6542, NULL),
(6543, 'thunder', '/ˈθʌndər/', 'noun', '{"zh-TW":["雷聲"],"en":["the loud sound following lightning"]}', '{"root":{"text":"thunder","meaning":"resound (回響)"},"logic":"源自古英語 þunor（巨響）。"}', 'thunder and lightning / thunderstorm', '[{"en":"We heard thunder in the distance.","zh-TW":"我們聽到遠處的雷聲。"},{"en":"The dog is afraid of thunder.","zh-TW":"這隻狗怕打雷。"}]', '{"noun":"thunderstorm","adjective":"thunderous"}', NULL, 3, 6543, NULL),
(6544, 'ticket', '/ˈtɪkɪt/', 'noun', '{"zh-TW":["工單；票單"],"en":["a record of a service request or issue submitted to a support team"]}', NULL, 'open a ticket / resolve a ticket / support ticket / ticket queue', '[{"en":"A support ticket was opened for the billing error.","zh-TW":"為帳單錯誤開立了一張支援工單。"},{"en":"The ticket was escalated to the second-level support team.","zh-TW":"工單被升級到第二級支援團隊。"}]', '{"verb":"ticket","plural":"tickets"}', NULL, 2, 6544, NULL),
(6545, 'tight', '/taɪt/', 'adjective', '{"zh-TW":["緊的；嚴格的","資金緊張的"],"en":["fixed or held firmly","limited or restricted"]}', NULL, 'tight deadline / tight budget / tight schedule', '[{"en":"We are working under a very tight deadline.","zh-TW":"我們在非常緊迫的截止日期下工作。"},{"en":"The budget is tight this quarter.","zh-TW":"本季度預算緊張。"}]', '{"adjective":"tight","adverb":"tightly","verb":"tighten"}', NULL, 2, 6545, NULL),
(6546, 'time', 'taɪm', 'noun', '{"zh-TW":["時間；次數","時期"],"en":["the progression of events","an instance or occasion"]}', NULL, 'lead time/full-time', '[{"en":"Delivery lead time is two weeks.","zh-TW":"交貨前置時間為兩週。"}]', '{"verb":"time","adjective":"timely","adverb":"timely"}', NULL, 1, 6546, NULL),
(6547, 'time management', '/taɪm ˈmænɪdʒmənt/', 'noun', '{"zh-TW":["時間管理"],"en":["the ability to plan and prioritize tasks to use time effectively"]}', NULL, 'time management skills / improve time management / time management tools', '[{"en":"Good time management allows professionals to meet multiple deadlines.","zh-TW":"良好的時間管理讓專業人士能夠達到多個截止日期。"},{"en":"She took a course on time management to boost her productivity.","zh-TW":"她參加了時間管理課程以提高生產力。"}]', '{"verb":"manage time"}', NULL, 5, 6547, NULL),
(6548, 'time value of money', '/taɪm ˈvæljuː əv ˈmʌni/', 'noun', '{"zh-TW":["貨幣時間價值"],"en":["the concept that money today is worth more than the same amount in the future"]}', NULL, 'apply time value of money / time value of money principle', '[{"en":"The time value of money is the basis for all discounted cash flow analysis.","zh-TW":"貨幣時間價值是所有折現現金流分析的基礎。"},{"en":"Understanding the time value of money is essential for financial planning.","zh-TW":"了解貨幣時間價值對財務規劃至關重要。"}]', NULL, NULL, 5, 6548, NULL),
(6549, 'time-sensitive', 'taɪm ˈsɛnsɪtɪv', 'adjective', '{"zh-TW":["時效性強的；緊迫的","有時間限制的"],"en":["needing to be done quickly","urgent"]}', NULL, 'time-sensitive request/time-sensitive matter', '[{"en":"This is a time-sensitive matter.","zh-TW":"這是一個時效性很強的事項。"}]', NULL, NULL, 5, 6549, NULL);
INSERT INTO words (word_id, word, phonetic, part_of_speech, definitions_json, analysis_json, collocation, examples_json, word_family_json, secondary_meaning_note, difficulty, frequency_rank, toeic_rank) VALUES
(6550, 'time-to-market', '/taɪm tuː ˈmɑːrkɪt/', 'noun', '{"zh-TW":["上市時間"],"en":["the time elapsed between a product''s conception and its availability for sale"]}', NULL, 'reduce time-to-market / faster time-to-market', '[{"en":"Agile development methods significantly reduced the product''s time-to-market.","zh-TW":"敏捷開發方法顯著縮短了產品的上市時間。"},{"en":"Shorter time-to-market gives companies a first-mover advantage.","zh-TW":"較短的上市時間為公司提供了先發優勢。"}]', NULL, NULL, 5, 6550, NULL),
(6551, 'timeline', '/ˈtaɪmlaɪn/', 'noun', '{"zh-TW":["時間表；時間軸"],"en":["a schedule showing the order and timing of events"]}', NULL, 'project timeline / revise the timeline', '[{"en":"The project timeline was extended by two weeks.","zh-TW":"項目時間表延長了兩週。"},{"en":"All team members must adhere to the agreed timeline.","zh-TW":"所有團隊成員必須遵守商定的時間表。"}]', NULL, NULL, 3, 6551, 233),
(6552, 'timely', '/ˈtaɪmli/', 'adjective', '{"zh-TW":["及時的；適時的"],"en":["done at a suitable or opportune time"]}', NULL, 'timely manner / timely delivery / timely response', '[{"en":"Please respond in a timely manner.","zh-TW":"請及時回覆。"},{"en":"Timely delivery is crucial for customer satisfaction.","zh-TW":"及時交貨對客戶滿意度至關重要。"}]', '{"adjective":"timely","noun":"timeliness"}', NULL, 2, 6552, NULL),
(6553, 'timely delivery', '/ˈtaɪmli dɪˈlɪvəri/', 'noun', '{"zh-TW":["及時交付；準時交貨"],"en":["the delivery of goods or services within the agreed timeframe"]}', NULL, 'ensure timely delivery / timely delivery performance', '[{"en":"Timely delivery is a key performance metric for logistics providers.","zh-TW":"及時交付是物流供應商的關鍵績效指標。"},{"en":"Failure to ensure timely delivery may trigger penalties under the contract.","zh-TW":"未能確保及時交付可能觸發合約下的罰款。"}]', NULL, NULL, 5, 6553, NULL),
(6554, 'timetable', '/''taɪmˌteɪbəl/', 'noun', '{"zh-TW":["時刻表；時間表"],"en":["a chart showing the departure and arrival times of trains, buses, or other public transport"]}', NULL, 'check the timetable / train timetable / bus timetable', '[{"en":"We checked the ferry timetable to plan our day on the island.","zh-TW":"我們查看了渡輪時刻表，規劃在島上的一天。"},{"en":"The timetable showed that the next direct bus would not leave for three hours.","zh-TW":"時刻表顯示下一班直達巴士要三小時後才出發。"}]', NULL, NULL, 3, 6554, NULL),
(6555, 'tip', '/tɪp/', 'noun', '{"zh-TW":["小費"],"en":["a sum of money given to a service worker"]}', NULL, 'leave a tip / generous tip', '[{"en":"It is customary to leave a 15 to 20 percent tip.","zh-TW":"習慣上會留下15到20%的小費。"},{"en":"The waiter was pleased with the generous tip.","zh-TW":"服務生對豐厚的小費感到高興。"}]', '{"verb":"tip"}', NULL, 1, 6555, NULL),
(6556, 'tipping point', '/ˈtɪpɪŋ pɔɪnt/', 'noun', '{"zh-TW":["臨界點；引爆點"],"en":["a critical threshold beyond which a change becomes self-reinforcing"]}', NULL, 'reach a tipping point / climate tipping point / cross a tipping point', '[{"en":"Scientists warn that we may be approaching dangerous climate tipping points.","zh-TW":"科學家警告說我們可能正在接近危險的氣候臨界點。"},{"en":"The movement reached a tipping point when a million people marched.","zh-TW":"當一百萬人遊行時，這場運動達到了臨界點。"}]', NULL, NULL, 5, 6556, NULL),
(6557, 'title', '/ˈtaɪtəl/', 'noun', '{"zh-TW":["產權；所有權"],"en":["legal ownership of property"]}', NULL, 'clear title / title search / transfer title / title deed', '[{"en":"The title was transferred to the new owner after completion.","zh-TW":"產權在交割後轉移給新業主。"},{"en":"A title search confirmed there were no liens on the property.","zh-TW":"產權搜查確認物業上沒有留置權。"}]', '{"adjective":"titled"}', NULL, 2, 6557, NULL),
(6558, 'title deed', '/ˈtaɪtəl diːd/', 'noun', '{"zh-TW":["產權契據；地契"],"en":["a legal document proving ownership of a property"]}', NULL, 'transfer title deed / register title deed', '[{"en":"The title deed was transferred to the buyer after full payment.","zh-TW":"全額付款後，產權契據轉讓給了買方。"},{"en":"A bank holds the title deed as security for a mortgage.","zh-TW":"銀行持有產權契據作為抵押貸款的擔保。"}]', NULL, NULL, 4, 6558, NULL),
(6559, 'tokenization', '/ˌtəʊkənaɪˈzeɪʃən/', 'noun', '{"zh-TW":["標記化；令牌化"],"en":["splitting text into tokens for processing; replacing sensitive data with tokens"]}', NULL, 'NLP tokenization / data tokenization / payment tokenization', '[{"en":"Tokenization of payment data replaces card numbers with secure tokens.","zh-TW":"支付數據標記化用安全令牌替換卡號。"},{"en":"NLP models require tokenization of text before processing.","zh-TW":"NLP模型在處理前需要對文本進行標記化。"}]', '{"verb":"tokenize","adjective":"tokenized"}', NULL, 4, 6559, NULL),
(6560, 'tolerance', '/ˈtɑːlərəns/', 'noun', '{"zh-TW":["容忍；寬容","公差"],"en":["willingness to accept differences","the allowable variation"]}', NULL, 'zero tolerance / risk tolerance / tolerance level', '[{"en":"The company has a zero-tolerance policy on harassment.","zh-TW":"公司對騷擾採取零容忍政策。"},{"en":"Investors have different levels of risk tolerance.","zh-TW":"投資者有不同程度的風險承受力。"}]', '{"noun":"tolerance","verb":"tolerate","adjective":"tolerant, tolerable"}', NULL, 3, 6560, NULL),
(6561, 'tolerant', '/ˈtɒlərənt/', 'adjective', '{"zh-TW":["容忍的；寬容的"],"en":["willing to accept views or behavior different from one''s own"]}', '{"root":{"text":"toler","meaning":"endure (忍受)"},"suffix":{"text":"-ant","meaning":"being (…的)"},"logic":"能忍受差異的，即「寬容的」。"}', 'tolerant of / tolerant society', '[{"en":"We should be tolerant of different opinions.","zh-TW":"我們應該容忍不同的意見。"},{"en":"She is very tolerant of her coworkers.","zh-TW":"她對同事很寬容。"}]', '{"noun":"tolerance","verb":"tolerate"}', NULL, 3, 6561, NULL),
(6562, 'tonal language', '/''toʊnəl ˌlæŋɡwɪdʒ/', 'noun', '{"zh-TW":["聲調語言"],"en":["a language in which the tone or pitch used when pronouncing a word changes its meaning"]}', NULL, 'study a tonal language / tonal language learner / characteristics of tonal language', '[{"en":"Mandarin Chinese is a tonal language where the same syllable can have multiple meanings.","zh-TW":"普通話是一種聲調語言，其中同一音節可以有多種含義。"},{"en":"Learning a tonal language requires training the ear to distinguish subtle pitch differences.","zh-TW":"學習聲調語言需要訓練耳朵辨別細微的音調差異。"}]', '{"adjective":"tonal"}', NULL, 5, 6562, NULL),
(6563, 'tone', '/toʊn/', 'noun', '{"zh-TW":["語氣；風格"],"en":["the general character or attitude conveyed in written or spoken communication"]}', NULL, 'professional tone / formal tone / conversational tone', '[{"en":"The memo used a formal tone appropriate for the board.","zh-TW":"備忘錄使用了適合董事會的正式語氣。"},{"en":"Adjust the tone of your email to match the relationship with the recipient.","zh-TW":"調整電子郵件的語氣以配合與收件人的關係。"}]', '{"adjective":"tonal"}', NULL, 1, 6563, NULL),
(6564, 'tone of voice', '/''təʊn əv vɔɪs/', 'noun', '{"zh-TW":["語氣；說話的語調"],"en":["the way you express your feelings or attitude through the quality of your voice"]}', NULL, 'appropriate tone of voice / adapt tone of voice / professional tone of voice', '[{"en":"Her calm tone of voice reassured the anxious customer immediately.","zh-TW":"她平靜的語氣立即讓焦慮的客戶感到安心。"},{"en":"A manager''s tone of voice can significantly affect team morale.","zh-TW":"管理者的語氣可以顯著影響團隊士氣。"}]', NULL, NULL, 5, 6564, NULL),
(6565, 'tool', '/tuːl/', 'noun', '{"zh-TW":["工具；手段"],"en":["a device or implement used for a task"]}', NULL, 'management tool / software tool / essential tool', '[{"en":"Data analytics is an essential business tool.","zh-TW":"數據分析是重要的商業工具。"},{"en":"The new software tool streamlines our workflow.","zh-TW":"新的軟體工具簡化了我們的工作流程。"}]', '{"noun":"tool, toolkit"}', NULL, 1, 6565, NULL),
(6566, 'top line', '/ˈtɒp laɪn/', 'noun', '{"zh-TW":["頂線；總收入"],"en":["a company''s gross revenue or total sales before deductions"]}', NULL, 'grow the top line / top-line revenue / top-line growth', '[{"en":"Strong top-line growth attracted new investors.","zh-TW":"強勁的總收入增長吸引了新投資者。"},{"en":"Marketing investments are intended to drive top-line expansion.","zh-TW":"行銷投資旨在推動總收入擴張。"}]', NULL, NULL, 3, 6566, NULL),
(6567, 'top management', '/tɒp ˈmænɪdʒmənt/', 'noun', '{"zh-TW":["最高管理層；頂層管理"],"en":["the most senior level of management in an organization"]}', NULL, 'report to top management / top management decision', '[{"en":"Top management approved the multi-year investment plan.","zh-TW":"最高管理層批准了多年投資計劃。"},{"en":"Changes of this scale require buy-in from top management.","zh-TW":"這種規模的變化需要最高管理層的支持。"}]', NULL, NULL, 5, 6567, NULL),
(6568, 'top-line growth', '/tɒp laɪn ɡroʊθ/', 'noun', '{"zh-TW":["頂線增長；收入增長"],"en":["growth in a company''s total revenue or gross sales"]}', NULL, 'report top-line growth / drive top-line growth', '[{"en":"The company achieved 20% top-line growth driven by new markets.","zh-TW":"公司依靠新市場實現了20%的頂線增長。"},{"en":"Top-line growth does not always translate into bottom-line improvement.","zh-TW":"頂線增長並不總是轉化為淨利潤的改善。"}]', '{"opposite":"bottom-line growth"}', NULL, 5, 6568, NULL),
(6569, 'topic', '/ˈtɑːpɪk/', 'noun', '{"zh-TW":["主題；話題"],"en":["a matter dealt with in discussion"]}', NULL, 'on topic / hot topic / change the topic', '[{"en":"Sustainability is a hot topic in business today.","zh-TW":"永續性是當今商業的熱門話題。"},{"en":"Let''s stay on topic during the meeting.","zh-TW":"讓我們在會議中保持主題不偏離。"}]', '{"noun":"topic","adjective":"topical"}', NULL, 2, 6569, NULL),
(6570, 'tornado', '/tɔːrˈneɪdoʊ/', 'noun', '{"zh-TW":["龍捲風"],"en":["a violently rotating column of air"]}', '{"root":{"text":"tornado","meaning":"turn (旋轉)"},"logic":"源自西班牙語 tornar（轉），指旋轉的風柱。"}', 'tornado warning / tornado alley', '[{"en":"The tornado destroyed dozens of houses.","zh-TW":"龍捲風摧毀了數十棟房屋。"},{"en":"Tornado warnings were issued for the entire county.","zh-TW":"全縣發布了龍捲風警報。"}]', NULL, NULL, 3, 6570, NULL),
(6571, 'tortious', '/ˈtɔːrʃəs/', 'adjective', '{"zh-TW":["侵權的；構成侵權行為的"],"en":["relating to or constituting a tort in law"]}', NULL, 'tortious conduct / tortious interference / tortious act', '[{"en":"The company was held liable for tortious interference with a contract.","zh-TW":"公司因侵權干涉合約而被認定承擔責任。"},{"en":"Tortious misconduct can give rise to civil claims for compensation.","zh-TW":"侵權行為可引起民事賠償索賠。"}]', '{"noun":"tort","adverb":"tortiously"}', NULL, 3, 6571, NULL),
(6572, 'total', '/ˈtoʊtl/', 'noun, adjective, verb', '{"zh-TW":["總計；全部的","合計"],"en":["the complete amount","to amount to"]}', NULL, 'in total / total cost / total revenue', '[{"en":"The total cost of the project is $2 million.","zh-TW":"專案總成本為兩百萬美元。"},{"en":"Sales totaled $5 million this quarter.","zh-TW":"本季銷售額合計五百萬美元。"}]', '{"noun":"total, totality","adjective":"total","adverb":"totally","verb":"total"}', NULL, 2, 6572, NULL),
(6573, 'total addressable market', '/ˈtoʊtəl əˈdresəbl ˈmɑːrkɪt/', 'noun', '{"zh-TW":["可觸及市場總量；市場潛在總量"],"en":["the total revenue opportunity available if a product reaches every potential customer"]}', NULL, 'estimate total addressable market / total addressable market size', '[{"en":"The startup estimated a total addressable market of $5 billion.","zh-TW":"初創企業估計可觸及市場總量為50億元。"},{"en":"Understanding total addressable market helps justify investment in a new product.","zh-TW":"了解可觸及市場總量有助於為新產品的投資提供依據。"}]', '{"abbreviation":"TAM"}', NULL, 5, 6573, NULL),
(6574, 'total cost of ownership', '/ˈtoʊtəl kɒst əv ˈoʊnərʃɪp/', 'noun', '{"zh-TW":["總擁有成本"],"en":["the full cost of a product or system over its entire lifetime"]}', NULL, 'calculate total cost of ownership / reduce total cost of ownership', '[{"en":"Total cost of ownership includes purchase, maintenance, and disposal costs.","zh-TW":"總擁有成本包括購買、維護和處置成本。"},{"en":"Choosing the cheapest option ignores the total cost of ownership.","zh-TW":"選擇最便宜的選項忽視了總擁有成本。"}]', '{"abbreviation":"TCO"}', NULL, 5, 6574, NULL),
(6575, 'total quality management', '/ˈtoʊtəl ˈkwɒlɪti ˈmænɪdʒmənt/', 'noun', '{"zh-TW":["全面品質管理"],"en":["a management approach focused on continuous quality improvement"]}', NULL, 'implement TQM / total quality management principles / TQM culture', '[{"en":"Total quality management helped reduce defect rates to near zero.","zh-TW":"全面品質管理幫助將缺陷率降至接近零。"},{"en":"TQM requires commitment from every level of the organization.","zh-TW":"全面品質管理需要組織每個層級的承諾。"}]', '{"abbreviation":"TQM"}', NULL, 5, 6575, NULL),
(6576, 'total return', '/ˈtoʊtəl rɪˈtɜːrn/', 'noun', '{"zh-TW":["總回報"],"en":["the full gain from an investment including income and capital appreciation"]}', NULL, 'calculate total return / total return investment strategy', '[{"en":"The bond''s total return over three years was 18%.","zh-TW":"債券三年的總回報為18%。"},{"en":"A total return approach considers both dividends and price appreciation.","zh-TW":"總回報方法同時考慮股息和價格升值。"}]', NULL, NULL, 4, 6576, NULL),
(6577, 'total revenue', '/ˈtoʊtəl ˈrevɪnjuː/', 'noun', '{"zh-TW":["總收入"],"en":["the total income generated from sales of goods or services before deductions"]}', NULL, 'report total revenue / increase total revenue', '[{"en":"Total revenue for the year reached $80 million.","zh-TW":"全年總收入達到了8000萬元。"},{"en":"Total revenue growth of 12% exceeded analyst expectations.","zh-TW":"12%的總收入增長超過了分析師預期。"}]', NULL, NULL, 5, 6577, NULL),
(6578, 'total rewards', '/ˈtoʊtəl rɪˈwɔːrdz/', 'noun', '{"zh-TW":["全面薪酬"],"en":["the complete package of financial and non-financial benefits offered to employees"]}', NULL, 'total rewards strategy / total rewards framework / total rewards package', '[{"en":"The total rewards package includes health, wellness, and financial benefits.","zh-TW":"全面薪酬方案包括健康、健康和財務福利。"},{"en":"A competitive total rewards strategy helps attract top talent.","zh-TW":"具競爭力的全面薪酬策略有助於吸引頂尖人才。"}]', NULL, NULL, 5, 6578, NULL),
(6579, 'total shareholder return', '/ˈtəʊtəl ˈʃeəhəʊldər rɪˈtɜːrn/', 'noun', '{"zh-TW":["股東總回報"],"en":["a measure of financial performance combining capital gains and dividends"]}', NULL, 'calculate total shareholder return / maximize total shareholder return / benchmark total shareholder return', '[{"en":"The board''s remuneration was linked to total shareholder return over three years.","zh-TW":"董事會的薪酬與三年內的股東總回報掛鉤。"},{"en":"Total shareholder return is widely used to compare investment performance.","zh-TW":"股東總回報被廣泛用於比較投資業績。"}]', NULL, NULL, 5, 6579, NULL),
(6580, 'touch', '/tʌtʃ/', 'noun, verb', '{"zh-TW":["【主要意義-動詞/名詞】觸碰；接觸","【次要意義-名詞】少量；一點點（a touch of）","【次要意義-動詞】感動；使感動","【次要意義-動詞】涉及；關係到（通常用否定）"],"en":["[primary] to make contact with something; the sense of feeling","[secondary - noun] a very small amount of something","[secondary - verb] to affect emotionally; to move someone","[secondary - verb] to concern or relate to (usually in negative forms)"]}', NULL, 'a touch of class / in touch / keep in touch / touch on / touch base', '[{"en":"His speech touched everyone in the room deeply.","zh-TW":"他的演講深深感動了在場的每一個人。"},{"en":"The report touches on several key issues facing the industry.","zh-TW":"報告涉及了行業面臨的幾個關鍵問題。"},{"en":"Please touch base with the client before sending the final proposal.","zh-TW":"在發送最終提案之前，請先與客戶聯絡確認。"}]', '{"adjective":"touching, untouched","noun":"touchstone"}', 'a touch of（一點點）、touch on（涉及）、touch base（聯絡確認）、keep in touch（保持聯絡）均是 TOEIC 職場溝通文章的高頻表達。', 2, 6580, NULL),
(6581, 'touchpoint', '/ˈtʌtʃpɔɪnt/', 'noun', '{"zh-TW":["接觸點"],"en":["any interaction a customer has with a brand during the buying journey"]}', NULL, 'customer touchpoint / map touchpoints / optimize touchpoints', '[{"en":"Each touchpoint is an opportunity to improve customer satisfaction.","zh-TW":"每個接觸點都是提高客戶滿意度的機會。"},{"en":"The customer journey map identifies all key touchpoints.","zh-TW":"客戶旅程圖識別了所有關鍵接觸點。"}]', '{"plural":"touchpoints"}', NULL, 4, 6581, NULL),
(6582, 'tour guide', '/tʊər ɡaɪd/', 'noun', '{"zh-TW":["導遊"],"en":["a person who guides tourists"]}', NULL, 'experienced tour guide / local tour guide', '[{"en":"Our tour guide was very knowledgeable about local history.","zh-TW":"我們的導遊對當地歷史非常了解。"},{"en":"The tour guide led the group through the museum.","zh-TW":"導遊帶領團體參觀博物館。"}]', NULL, NULL, 4, 6582, NULL),
(6583, 'tourist attraction', '/''tʊərɪst əˌtrækʃən/', 'noun', '{"zh-TW":["旅遊景點；觀光景點"],"en":["a place of interest visited by tourists"]}', NULL, 'popular tourist attraction / visit a tourist attraction / must-see tourist attraction', '[{"en":"The ancient temple is the most popular tourist attraction in the region.","zh-TW":"這座古廟是該地區最受歡迎的旅遊景點。"},{"en":"She visited all the must-see tourist attractions during her week in the city.","zh-TW":"她在城市的一週內參觀了所有必看的旅遊景點。"}]', NULL, NULL, 5, 6583, NULL),
(6584, 'tourist trap', '/''tʊərɪst træp/', 'noun', '{"zh-TW":["觀光陷阱；宰客景點"],"en":["a place that attracts many tourists and charges high prices for mediocre products or services"]}', NULL, 'avoid tourist traps / typical tourist trap / recognize a tourist trap', '[{"en":"She asked a local for recommendations to avoid the tourist traps near the waterfront.","zh-TW":"她向當地人詢問推薦，以避開海濱附近的觀光陷阱。"},{"en":"The restaurant near the main square was a tourist trap with overpriced food.","zh-TW":"主廣場附近的餐廳是一個食物價格過高的觀光陷阱。"}]', NULL, NULL, 4, 6584, NULL),
(6585, 'tourist visa', '/''tʊərɪst ˈviːzə/', 'noun', '{"zh-TW":["觀光簽證；旅遊簽證"],"en":["official permission to enter a country for leisure or sightseeing purposes"]}', NULL, 'apply for a tourist visa / tourist visa requirement / obtain a tourist visa', '[{"en":"She applied for a tourist visa three weeks before her scheduled trip.","zh-TW":"她在預定旅行前三週申請了觀光簽證。"},{"en":"Some countries offer a tourist visa on arrival for certain passport holders.","zh-TW":"一些國家為特定護照持有人提供落地觀光簽證。"}]', NULL, NULL, 4, 6585, NULL),
(6586, 'tournament', '/ˈtɜːrnəmənt/', 'noun', '{"zh-TW":["錦標賽；比賽"],"en":["a competition with many games"]}', NULL, 'tennis tournament / enter a tournament', '[{"en":"She entered the tennis tournament.","zh-TW":"她參加了網球錦標賽。"},{"en":"The tournament lasts two weeks.","zh-TW":"比賽持續兩週。"}]', NULL, NULL, 4, 6586, NULL),
(6587, 'town', 'taʊn', 'noun', '{"zh-TW":["城鎮；市區","城市"],"en":["a place smaller than a city","an urban area"]}', NULL, 'hometown/small town', '[{"en":"The new factory is located in a small town.","zh-TW":"新工廠位於一個小鎮。"}]', '{"adjective":"town-based"}', NULL, 1, 6587, NULL),
(6588, 'trace', '/treɪs/', 'noun, verb', '{"zh-TW":["痕跡；蹤跡","追蹤；追溯"],"en":["a mark or sign of something","to find or follow"]}', NULL, 'trace back to / without a trace / trace the origin', '[{"en":"We traced the error back to a software bug.","zh-TW":"我們將錯誤追溯到一個軟體漏洞。"},{"en":"There is no trace of the missing shipment.","zh-TW":"失蹤的貨物沒有任何蹤跡。"}]', '{"noun":"trace, traceability","verb":"trace","adjective":"traceable"}', NULL, 2, 6588, NULL),
(6589, 'traceability', '/''treɪsəˌbɪlɪti/', 'noun', '{"zh-TW":["可追溯性；追蹤能力"],"en":["the ability to track the movement and origin of products through the supply chain"]}', NULL, 'ensure traceability / improve traceability / food traceability', '[{"en":"Traceability systems allow consumers to track the origin of their food products.","zh-TW":"可追溯性系統讓消費者可以追蹤其食品的來源。"},{"en":"Blockchain technology is being used to enhance traceability in global supply chains.","zh-TW":"區塊鏈技術正被用於增強全球供應鏈的可追溯性。"}]', '{"adjective":"traceable","verb":"trace"}', NULL, 4, 6589, NULL),
(6590, 'track', '/træk/', 'noun, verb', '{"zh-TW":["軌道；途徑","追蹤；跟蹤"],"en":["a path or course","to follow the progress of"]}', NULL, 'keep track of / track record / on track', '[{"en":"We need to keep track of all expenses.","zh-TW":"我們需要追蹤所有費用。"},{"en":"The project is on track for completion in June.","zh-TW":"專案按計畫將在六月完成。"}]', '{"noun":"track, tracker, tracking","verb":"track"}', NULL, 2, 6590, NULL),
(6591, 'track and field', '/''træk ən fiːld/', 'noun', '{"zh-TW":["田徑運動"],"en":["a collection of sporting events that involve competitive running, jumping, and throwing"]}', NULL, 'compete in track and field / track and field event / track and field athlete', '[{"en":"She excelled in track and field events, particularly the high jump.","zh-TW":"她在田徑運動比賽中表現出色，尤其是跳高項目。"},{"en":"The school''s track and field team trains every afternoon after school.","zh-TW":"學校的田徑隊每天下午放學後訓練。"}]', NULL, NULL, 5, 6591, NULL),
(6592, 'track and trace', '/''træk ən treɪs/', 'noun', '{"zh-TW":["追蹤與追溯；貨物追蹤"],"en":["a system that enables the tracking of shipments in real time from origin to destination"]}', NULL, 'use track and trace / track and trace system / real-time track and trace', '[{"en":"The carrier''s track and trace system allowed customers to monitor their delivery.","zh-TW":"承運人的追蹤系統使客戶能夠監控他們的貨物配送。"},{"en":"Track and trace technology improves transparency in the supply chain.","zh-TW":"追蹤技術提高了供應鏈的透明度。"}]', NULL, NULL, 5, 6592, NULL),
(6593, 'trackable delivery', '/''trækəbəl dɪˌlɪvəri/', 'noun', '{"zh-TW":["可追蹤配送；有追蹤號碼的快遞"],"en":["a delivery service that allows the sender and recipient to monitor the progress of a package"]}', NULL, 'use trackable delivery / trackable delivery service / provide trackable delivery', '[{"en":"She chose trackable delivery to ensure she could monitor her package at every stage.","zh-TW":"她選擇了可追蹤配送，以確保她能夠監控包裹的每個階段。"},{"en":"Trackable delivery reduces customer inquiries and increases confidence in the service.","zh-TW":"可追蹤配送減少了客戶詢問並提高了對服務的信心。"}]', NULL, NULL, 5, 6593, NULL),
(6594, 'tracking', '/ˈtrækɪŋ/', 'noun', '{"zh-TW":["追蹤；跟蹤"],"en":["monitoring the location and status of a shipment in transit"]}', NULL, 'package tracking / shipment tracking / real-time tracking', '[{"en":"Customers can monitor deliveries using the online tracking system.","zh-TW":"客戶可以使用線上追蹤系統監控交付情況。"},{"en":"GPS tracking improved visibility across the entire supply chain.","zh-TW":"GPS追蹤提高了整個供應鏈的能見度。"}]', '{"verb":"track","adjective":"tracked"}', NULL, 3, 6594, NULL),
(6595, 'tracking number', '/ˈtræktɪŋ ˈnʌmbər/', 'noun', '{"zh-TW":["追蹤號碼"],"en":["a unique code used to monitor the progress of a shipment"]}', NULL, 'receive a tracking number / enter a tracking number', '[{"en":"Use the tracking number to check your delivery status.","zh-TW":"使用追蹤號碼查看您的配送狀態。"},{"en":"You will receive a tracking number once the order is dispatched.","zh-TW":"訂單發出後您將收到追蹤號碼。"}]', NULL, NULL, 5, 6595, NULL),
(6596, 'trade', '/treɪd/', 'noun, verb', '{"zh-TW":["貿易；交易","交易；經商"],"en":["the buying and selling of goods","to engage in commerce"]}', NULL, 'international trade / trade agreement / free trade', '[{"en":"International trade expanded rapidly last year.","zh-TW":"去年國際貿易迅速擴張。"},{"en":"The two countries signed a free trade agreement.","zh-TW":"兩國簽署了自由貿易協定。"}]', '{"noun":"trade, trader, trading","verb":"trade"}', NULL, 2, 6596, NULL),
(6597, 'trade agreement', '/treɪd əˈɡriːmənt/', 'noun', '{"zh-TW":["貿易協定"],"en":["a treaty between countries to facilitate trade"]}', NULL, 'sign a trade agreement / bilateral trade agreement', '[{"en":"The two countries signed a trade agreement to reduce tariffs.","zh-TW":"兩國簽署了減少關稅的貿易協定。"},{"en":"Regional trade agreements have expanded markets for exporters.","zh-TW":"區域貿易協定為出口商擴大了市場。"}]', NULL, NULL, 5, 6597, NULL),
(6598, 'trade association', '/treɪd əˌsoʊsiˈeɪʃən/', 'noun', '{"zh-TW":["行業協會"],"en":["an organization formed by businesses in the same industry to promote common interests"]}', NULL, 'join a trade association / trade association membership', '[{"en":"The company joined the trade association to influence industry regulations.","zh-TW":"公司加入了行業協會以影響行業法規。"},{"en":"Trade associations provide networking, advocacy, and industry research.","zh-TW":"行業協會提供網絡建立、倡導和行業研究服務。"}]', NULL, NULL, 5, 6598, NULL),
(6599, 'trade balance', '/treɪd ˈbæləns/', 'noun', '{"zh-TW":["貿易差額；貿易平衡"],"en":["the difference between a country''s exports and imports"]}', NULL, 'trade balance surplus / trade balance deficit / improve the trade balance', '[{"en":"The country reported a trade balance deficit for the third consecutive year.","zh-TW":"該國連續第三年報告貿易逆差。"},{"en":"A trade balance surplus strengthens the domestic currency.","zh-TW":"貿易順差鞏固了本國貨幣。"}]', NULL, NULL, 5, 6599, NULL);
INSERT INTO words (word_id, word, phonetic, part_of_speech, definitions_json, analysis_json, collocation, examples_json, word_family_json, secondary_meaning_note, difficulty, frequency_rank, toeic_rank) VALUES
(6600, 'trade barrier', '/treɪd ˈbæriər/', 'noun', '{"zh-TW":["貿易壁壘"],"en":["a government restriction that limits free trade between countries"]}', NULL, 'impose a trade barrier / remove trade barriers', '[{"en":"Tariffs and quotas are common forms of trade barriers.","zh-TW":"關稅和配額是常見形式的貿易壁壘。"},{"en":"Free trade agreements aim to reduce trade barriers between signatories.","zh-TW":"自由貿易協議旨在減少簽署方之間的貿易壁壘。"}]', NULL, NULL, 5, 6600, NULL),
(6601, 'trade credit', '/treɪd ˈkredɪt/', 'noun', '{"zh-TW":["商業信貸；貿易信用"],"en":["supplier credit allowing buyers to pay for goods after receipt"]}', NULL, 'use trade credit / trade credit terms / trade credit facility', '[{"en":"The company uses 60-day trade credit to manage cash flow.","zh-TW":"公司使用60天商業信貸來管理現金流。"},{"en":"Trade credit is the most common form of short-term financing.","zh-TW":"商業信貸是最常見的短期融資形式。"}]', NULL, NULL, 4, 6601, NULL),
(6602, 'trade deficit', '/treɪd ˈdefɪsɪt/', 'noun', '{"zh-TW":["貿易逆差"],"en":["when a country imports more than it exports"]}', NULL, 'large trade deficit / reduce the trade deficit / persistent trade deficit', '[{"en":"The trade deficit widened as imports grew faster than exports.","zh-TW":"由於進口增速超過出口，貿易逆差擴大了。"},{"en":"The government sought to reduce the trade deficit through export promotion.","zh-TW":"政府通過促進出口尋求縮小貿易逆差。"}]', NULL, NULL, 5, 6602, NULL),
(6603, 'trade discount', '/treɪd ˈdɪskaʊnt/', 'noun', '{"zh-TW":["貿易折扣；商業折扣"],"en":["a discount given to businesses purchasing goods for resale"]}', NULL, 'offer a trade discount / receive a trade discount', '[{"en":"Retailers receive a 20% trade discount from the manufacturer.","zh-TW":"零售商從製造商獲得20%的貿易折扣。"},{"en":"A larger order size qualifies for a higher trade discount.","zh-TW":"較大的訂量可享有更高的貿易折扣。"}]', NULL, NULL, 5, 6603, NULL),
(6604, 'trade embargo', '/treɪd ɪmˈbɑːrɡoʊ/', 'noun', '{"zh-TW":["貿易禁運"],"en":["a government-imposed ban on trade with a particular country"]}', NULL, 'impose a trade embargo / trade embargo on imports', '[{"en":"The trade embargo restricted all exports to the targeted country.","zh-TW":"貿易禁運限制了對目標國家的所有出口。"},{"en":"A trade embargo can disrupt global supply chains and raise prices.","zh-TW":"貿易禁運可能會擾亂全球供應鏈並推高價格。"}]', NULL, NULL, 5, 6604, NULL),
(6605, 'trade exposure', '/treɪd ɪkˈspoʊʒər/', 'noun', '{"zh-TW":["貿易風險敞口"],"en":["the extent to which a business is affected by changes in international trade conditions"]}', NULL, 'manage trade exposure / reduce trade exposure', '[{"en":"The company''s trade exposure to China affects its earnings.","zh-TW":"公司對中國的貿易風險敞口影響其收益。"},{"en":"Hedging instruments are used to manage currency trade exposure.","zh-TW":"對沖工具用於管理貨幣貿易風險敞口。"}]', NULL, NULL, 5, 6605, NULL),
(6606, 'trade fair', '/treɪd fɛər/', 'noun', '{"zh-TW":["商展；貿易展覽會"],"en":["an exhibition where businesses display and promote their products"]}', NULL, 'attend a trade fair / exhibit at a trade fair', '[{"en":"The company exhibited its new products at the international trade fair.","zh-TW":"公司在國際商展上展示了其新產品。"},{"en":"Trade fairs offer excellent networking opportunities.","zh-TW":"商展提供了絕佳的拓展人脈機會。"}]', NULL, NULL, 4, 6606, NULL),
(6607, 'trade finance', '/treɪd ˈfaɪnæns/', 'noun', '{"zh-TW":["貿易融資"],"en":["financial instruments that facilitate international trade transactions"]}', NULL, 'use trade finance / trade finance solution', '[{"en":"Letters of credit and guarantees are key tools in trade finance.","zh-TW":"信用狀和擔保是貿易融資的關鍵工具。"},{"en":"Trade finance reduces payment risk for buyers and sellers in different countries.","zh-TW":"貿易融資降低了不同國家買賣雙方的付款風險。"}]', NULL, NULL, 5, 6607, NULL),
(6608, 'trade license', '/treɪd ˈlaɪsəns/', 'noun', '{"zh-TW":["營業執照"],"en":["official permission granted to operate a business in a jurisdiction"]}', NULL, 'obtain a trade license / renew a trade license', '[{"en":"All businesses must obtain a trade license before commencing operations.","zh-TW":"所有企業必須在開始經營前獲得營業執照。"},{"en":"The restaurant lost its trade license due to safety violations.","zh-TW":"餐廳因安全違規失去了營業執照。"}]', NULL, NULL, 5, 6608, NULL),
(6609, 'trade payable', '/treɪd ˈpeɪəbl/', 'noun', '{"zh-TW":["應付貿易帳款"],"en":["the amount a business owes to its suppliers for goods or services received"]}', NULL, 'manage trade payables / trade payable days', '[{"en":"The company extended its trade payable terms to 60 days.","zh-TW":"公司將應付貿易帳款條款延長到了60天。"},{"en":"Trade payables are listed as current liabilities on the balance sheet.","zh-TW":"應付貿易帳款在資產負債表上列為流動負債。"}]', NULL, NULL, 5, 6609, NULL),
(6610, 'trade payables', '/treɪd ˈpeɪəbəlz/', 'noun', '{"zh-TW":["應付帳款；商業應付款"],"en":["amounts owed by a company to suppliers for goods and services received"]}', NULL, 'manage trade payables / trade payables balance', '[{"en":"Extending trade payables terms improved working capital.","zh-TW":"延長應付帳款條款改善了營運資金。"},{"en":"Trade payables are listed as current liabilities on the balance sheet.","zh-TW":"應付帳款在資產負債表上列為流動負債。"}]', NULL, NULL, 5, 6610, NULL),
(6611, 'trade receivables', '/treɪd rɪˈsiːvəbəlz/', 'noun', '{"zh-TW":["貿易應收帳款"],"en":["amounts owed by customers for goods or services already delivered"]}', NULL, 'collect trade receivables / trade receivables balance', '[{"en":"The company reported a 10 million increase in trade receivables.","zh-TW":"公司報告貿易應收帳款增加了1000萬元。"},{"en":"Trade receivables are listed under current assets on the balance sheet.","zh-TW":"貿易應收帳款在資產負債表上列為流動資產。"}]', NULL, NULL, 5, 6611, NULL),
(6612, 'trade route', '/''treɪd ruːt/', 'noun', '{"zh-TW":["貿易路線；商路"],"en":["a route historically established for commercial exchange of goods between regions"]}', NULL, 'ancient trade route / major trade route / global trade route', '[{"en":"The Silk Road was one of the most important trade routes in ancient history.","zh-TW":"絲綢之路是古代歷史上最重要的貿易路線之一。"},{"en":"Modern sea trade routes carry the vast majority of global merchandise trade.","zh-TW":"現代海上貿易路線承載了全球大部分商品貿易。"}]', NULL, NULL, 4, 6612, NULL),
(6613, 'trade secret', '/treɪd ˈsiːkrɪt/', 'noun', '{"zh-TW":["商業機密"],"en":["confidential business information that provides a competitive edge"]}', NULL, 'protect trade secrets / trade secret protection / misappropriate trade secrets', '[{"en":"The formula is a closely guarded trade secret.","zh-TW":"這個配方是一個嚴格保守的商業機密。"},{"en":"Employees sign NDAs to protect the company''s trade secrets.","zh-TW":"員工簽署保密協議以保護公司的商業機密。"}]', '{"plural":"trade secrets"}', NULL, 4, 6613, NULL),
(6614, 'trade show', '/treɪd ʃoʊ/', 'noun', '{"zh-TW":["貿易展；行業展覽"],"en":["an exhibition where companies display products to potential buyers"]}', NULL, 'attend a trade show / exhibit at a trade show / trade show booth', '[{"en":"The company showcased its new product at the annual trade show.","zh-TW":"公司在年度貿易展上展示了新產品。"},{"en":"Trade shows are great for networking with industry peers.","zh-TW":"貿易展是與業界同行建立人際關係的好機會。"}]', '{"plural":"trade shows"}', NULL, 4, 6614, NULL),
(6615, 'trade surplus', '/treɪd ˈsɜːrpləs/', 'noun', '{"zh-TW":["貿易順差"],"en":["an excess of exports over imports in a country"]}', NULL, 'record a trade surplus / trade surplus data', '[{"en":"The country maintained a trade surplus for five consecutive years.","zh-TW":"該國連續五年維持貿易順差。"},{"en":"A trade surplus strengthens a country''s currency.","zh-TW":"貿易順差有助於增強一國貨幣的強度。"}]', NULL, NULL, 5, 6615, NULL),
(6616, 'trade union', '/treɪd ˈjuːniən/', 'noun', '{"zh-TW":["工會"],"en":["an organized association of workers formed to protect their rights"]}', NULL, 'join a trade union / trade union membership / trade union representative', '[{"en":"The trade union negotiated a 5% pay increase for its members.","zh-TW":"工會為其成員談判獲得5%的薪資增幅。"},{"en":"Trade unions play a key role in protecting workers'' rights.","zh-TW":"工會在保護工人權利方面發揮著關鍵作用。"}]', '{"plural":"trade unions"}', NULL, 4, 6616, NULL),
(6617, 'trade war', '/treɪd wɔːr/', 'noun', '{"zh-TW":["貿易戰"],"en":["economic conflict between countries involving tariffs and import restrictions"]}', NULL, 'trigger a trade war / trade war escalation / end a trade war', '[{"en":"The trade war between the two powers disrupted global supply chains.","zh-TW":"兩大國之間的貿易戰擾亂了全球供應鏈。"},{"en":"Companies restructured their supply chains to avoid trade war tariffs.","zh-TW":"企業重組了供應鏈以避免貿易戰關稅的影響。"}]', NULL, NULL, 3, 6617, NULL),
(6618, 'trade-off', '/ˈtreɪd ɒf/', 'noun', '{"zh-TW":["權衡；取捨"],"en":["a situation requiring a balance between two desirable but competing factors"]}', NULL, 'make a trade-off / trade-off between cost and quality', '[{"en":"The manager faced a trade-off between speed and accuracy.","zh-TW":"管理者面臨著速度和準確性之間的取捨。"},{"en":"Any business decision involves trade-offs between competing priorities.","zh-TW":"任何業務決策都涉及競爭優先事項之間的取捨。"}]', '{"verb":"trade off"}', NULL, 3, 6618, NULL),
(6619, 'trademark', '/ˈtreɪdmɑːrk/', 'noun', '{"zh-TW":["商標"],"en":["a symbol or name legally registered for a product"]}', NULL, 'registered trademark / trademark infringement', '[{"en":"Our logo is a registered trademark.","zh-TW":"我們的商標已經註冊。"},{"en":"Trademark infringement can lead to lawsuits.","zh-TW":"商標侵權可能導致訴訟。"}]', '{"noun":"trademark","verb":"trademark","adjective":"trademarked"}', NULL, 3, 6619, NULL),
(6620, 'trading halt', '/ˈtreɪdɪŋ hɔːlt/', 'noun', '{"zh-TW":["交易暫停"],"en":["a temporary suspension of trading in a security by the exchange"]}', NULL, 'announce a trading halt / resume trading after a halt', '[{"en":"A trading halt was called after the company released its profit warning.","zh-TW":"公司發布盈利預警後，交易暫停被宣佈。"},{"en":"Trading resumed after the one-hour halt.","zh-TW":"一小時暫停後恢復了交易。"}]', NULL, NULL, 4, 6620, NULL),
(6621, 'trading volume', '/ˈtreɪdɪŋ ˈvɒljuːm/', 'noun', '{"zh-TW":["交易量"],"en":["the total number of shares or contracts traded in a given period"]}', NULL, 'monitor trading volume / high trading volume', '[{"en":"Heavy trading volume accompanied the sharp rise in the stock price.","zh-TW":"大量的交易量伴隨著股價的急劇上漲。"},{"en":"Low trading volume can make it difficult to buy or sell a position quickly.","zh-TW":"低交易量可能使快速買入或賣出倉位變得困難。"}]', NULL, NULL, 5, 6621, NULL),
(6622, 'tradition', '/trəˈdɪʃn/', 'noun', '{"zh-TW":["傳統","傳統；慣例"],"en":["a custom or belief passed through generations","a long-established custom or belief"]}', '{"prefix":{"text":"tra-","meaning":"across (跨越)"},"root":{"text":"dit","meaning":"give (給予)"},"suffix":{"text":"-ion","meaning":"state (狀態)"},"logic":"跨越世代傳遞下來的東西，即「傳統」。"}', 'cultural tradition / family tradition; long tradition / by tradition / break with tradition', '[{"en":"It is a tradition to eat turkey on Thanksgiving.","zh-TW":"感恩節吃火雞是一項傳統。"},{"en":"We should respect local traditions.","zh-TW":"我們應該尊重當地傳統。"},{"en":"The company has a long tradition of innovation.","zh-TW":"公司有悠久的創新傳統。"},{"en":"They broke with tradition and appointed a young CEO.","zh-TW":"他們打破傳統任命了一位年輕的執行長。"}]', '{"adjective":"traditional","adverb":"traditionally","noun":"tradition"}', NULL, 3, 6622, NULL),
(6623, 'traditional', 'trəˈdɪʃənəl', 'adjective', '{"zh-TW":["傳統的；慣例的","常規的"],"en":["following old customs","long-established"]}', NULL, 'traditional method/traditional market', '[{"en":"The company uses both traditional and digital marketing.","zh-TW":"公司同時使用傳統和數字行銷。"}]', '{"noun":"tradition","adverb":"traditionally"}', NULL, 4, 6623, NULL),
(6624, 'traffic', '/ˈtræfɪk/', 'noun', '{"zh-TW":["交通；流量"],"en":["vehicles moving on roads; the amount of data"]}', NULL, 'web traffic / traffic congestion / traffic flow', '[{"en":"Website traffic increased by 40% after the campaign.","zh-TW":"活動後網站流量增加了40%。"},{"en":"Heavy traffic caused delays for commuters.","zh-TW":"交通擁堵導致通勤者延誤。"}]', '{"noun":"traffic"}', NULL, 3, 6624, NULL),
(6625, 'trail', '/''treɪl/', 'noun', '{"zh-TW":["小徑；登山步道"],"en":["a path or track through a forest or countryside"]}', NULL, 'hiking trail / nature trail / blaze a trail', '[{"en":"The national park has over fifty miles of marked hiking trails.","zh-TW":"這個國家公園有超過五十英里的標記登山步道。"},{"en":"She followed the trail through the forest to the waterfall.","zh-TW":"她沿著小徑穿過森林到達瀑布。"}]', '{"verb":"trail"}', NULL, 2, 6625, NULL),
(6626, 'trailblazer', '/''treɪlˌbleɪzər/', 'noun', '{"zh-TW":["先驅；開拓者"],"en":["a person who makes a new track through wild country; a pioneer; an innovator"]}', NULL, 'industry trailblazer / be a trailblazer / recognized as a trailblazer', '[{"en":"She is recognized as a trailblazer in the field of renewable energy.","zh-TW":"她被公認為可再生能源領域的先驅。"},{"en":"The company became a trailblazer by adopting paperless operations years before competitors.","zh-TW":"該公司在競爭對手之前多年採用無紙化運營，成為先驅。"}]', NULL, NULL, 4, 6626, NULL),
(6627, 'training', '/ˈtreɪnɪŋ/', 'noun', '{"zh-TW":["培訓；訓練"],"en":["teaching and practice of a skill"]}', NULL, 'employee training / training program', '[{"en":"New employees must complete a two-week training program.","zh-TW":"新員工必須完成兩週的培訓計劃。"},{"en":"Ongoing training keeps skills sharp and relevant.","zh-TW":"持續培訓保持技能的敏銳性和相關性。"}]', '{"verb":"train","noun":"trainer","adjective":"trained"}', NULL, 3, 6627, 469),
(6628, 'training needs analysis', '/ˈtreɪnɪŋ niːdz əˈnæləsɪs/', 'noun', '{"zh-TW":["培訓需求分析"],"en":["an assessment to identify skills gaps and determine training requirements"]}', NULL, 'conduct a training needs analysis / training needs analysis results', '[{"en":"The training needs analysis revealed a gap in project management skills.","zh-TW":"培訓需求分析揭示了項目管理技能方面的差距。"},{"en":"HR uses training needs analysis to plan the annual training calendar.","zh-TW":"人力資源部門使用培訓需求分析來規劃年度培訓日曆。"}]', NULL, NULL, 5, 6628, NULL),
(6629, 'trait', '/treɪt/', 'noun', '{"zh-TW":["特徵；特點"],"en":["a distinguishing quality or characteristic"]}', NULL, 'personality trait / key trait / leadership trait', '[{"en":"Adaptability is a key trait for managers.","zh-TW":"適應力是管理者的關鍵特質。"},{"en":"The company values creativity as a core trait.","zh-TW":"公司將創造力視為核心特質。"}]', '{"noun":"trait"}', NULL, 2, 6629, NULL),
(6630, 'trajectory', '/trəˈdʒektəri/', 'noun', '{"zh-TW":["軌跡；發展路徑"],"en":["the path followed by a projectile or object; the course of development of something"]}', NULL, 'career trajectory / growth trajectory / economic trajectory', '[{"en":"The company''s growth trajectory exceeded analysts'' expectations.","zh-TW":"公司的增長軌跡超出了分析師的預期。"},{"en":"Changing the emissions trajectory requires bold policy action within this decade.","zh-TW":"改變排放軌跡需要在這個十年內採取大膽的政策行動。"}]', NULL, NULL, 4, 6630, NULL),
(6631, 'tranche', '/trɑːnʃ/', 'noun', '{"zh-TW":["分期；批次；部分"],"en":["one of a number of portions in which something is divided"]}', NULL, 'senior tranche / equity tranche / funding tranche', '[{"en":"The first tranche of financing was released upon project commencement.","zh-TW":"第一批融資在項目開始時釋放。"},{"en":"Each tranche carries a different risk and return profile.","zh-TW":"每個部分帶有不同的風險和回報特徵。"}]', NULL, NULL, 3, 6631, NULL),
(6632, 'transaction', '/trænˈzækʃn/', 'noun', '{"zh-TW":["交易；事務"],"en":["an instance of buying or selling"]}', NULL, 'financial transaction / online transaction / transaction fee', '[{"en":"All transactions are recorded in the system.","zh-TW":"所有交易都記錄在系統中。"},{"en":"There is a small fee per transaction.","zh-TW":"每筆交易有少量手續費。"}]', '{"noun":"transaction","adjective":"transactional"}', NULL, 4, 6632, 234),
(6633, 'transaction cost', '/trænˈzækʃən kɒst/', 'noun', '{"zh-TW":["交易成本"],"en":["the costs incurred in executing a trade, purchase, or business transaction"]}', NULL, 'minimize transaction costs / transaction cost analysis', '[{"en":"Online trading platforms have significantly reduced transaction costs for investors.","zh-TW":"在線交易平台顯著降低了投資者的交易成本。"},{"en":"Transaction costs include brokerage fees, taxes, and administrative charges.","zh-TW":"交易成本包括經紀費、稅費和行政費用。"}]', NULL, NULL, 5, 6633, NULL),
(6634, 'transaction costs', '/trænˈzækʃən kɒsts/', 'noun', '{"zh-TW":["交易成本"],"en":["costs incurred when buying or selling goods, including information, negotiation, and enforcement costs"]}', NULL, 'reduce transaction costs / high transaction costs / transaction costs economics', '[{"en":"Digital platforms reduce transaction costs by connecting buyers and sellers more efficiently.","zh-TW":"數字平台通過更有效地連接買家和賣家來降低交易成本。"},{"en":"High transaction costs in real estate markets make property less liquid than financial assets.","zh-TW":"房地產市場的高交易成本使房產的流動性低於金融資產。"}]', NULL, NULL, 5, 6634, NULL),
(6635, 'transaction fee', '/trænsˈækʃən fiː/', 'noun', '{"zh-TW":["交易費用"],"en":["a charge applied when a financial transaction is processed"]}', NULL, 'waive a transaction fee / transaction fee structure', '[{"en":"International wire transfers carry a transaction fee.","zh-TW":"國際電匯需要支付交易費用。"},{"en":"Some credit cards offer no transaction fees on foreign purchases.","zh-TW":"某些信用卡對境外購物不收取交易費用。"}]', NULL, NULL, 5, 6635, NULL),
(6636, 'transaction processing', '/trænsˈækʃən ˈproʊsesɪŋ/', 'noun', '{"zh-TW":["交易處理"],"en":["the execution and recording of financial transactions"]}', NULL, 'transaction processing system / real-time transaction processing', '[{"en":"The bank''s transaction processing system handles millions of payments daily.","zh-TW":"銀行的交易處理系統每天處理數百萬筆付款。"},{"en":"Transaction processing speed improved after the system upgrade.","zh-TW":"系統升級後交易處理速度提高了。"}]', NULL, NULL, 5, 6636, NULL),
(6637, 'transcend', '/trænˈsend/', 'verb', '{"zh-TW":["超越；超出"],"en":["to be or go beyond the range or limits of"]}', NULL, 'transcend boundaries / transcend categories / transcend limitations', '[{"en":"The work transcends its cultural context to speak to universal themes.","zh-TW":"這部作品超越了其文化背景，觸及普世主題。"},{"en":"Innovation often requires the ability to transcend conventional thinking.","zh-TW":"創新往往需要超越傳統思維的能力。"}]', '{"noun":"transcendence","adjective":"transcendent"}', NULL, 3, 6637, NULL),
(6638, 'transcript', '/ˈtrænskrɪpt/', 'noun', '{"zh-TW":["成績單；謄本"],"en":["an official record of a student''s grades"]}', NULL, 'official transcript / academic transcript', '[{"en":"Send your official transcript to the school.","zh-TW":"將你的正式成績單寄到學校。"},{"en":"The transcript shows all courses taken.","zh-TW":"成績單顯示所有修過的課程。"}]', NULL, NULL, 4, 6638, NULL),
(6639, 'transcripts', '/''trænskrɪpts/', 'noun', '{"zh-TW":["成績單；學籍記錄"],"en":["official academic records showing a student''s courses taken and grades received"]}', NULL, 'official transcripts / request transcripts / submit transcripts', '[{"en":"International students must submit official transcripts translated into English.","zh-TW":"國際學生必須提交翻譯成英文的官方成績單。"},{"en":"The employer asked for university transcripts to verify her academic qualifications.","zh-TW":"雇主要求提供大學成績單以核實她的學術資格。"}]', '{"noun":"transcript"}', NULL, 4, 6639, NULL),
(6640, 'transfer', '/ˈtrænsfɜːr/', 'noun, verb', '{"zh-TW":["轉移；調動","轉移；轉讓"],"en":["the act of moving something","to move from one place to another"]}', NULL, 'transfer funds / knowledge transfer / transfer to', '[{"en":"She transferred to the London office.","zh-TW":"她調到了倫敦辦公室。"},{"en":"Please transfer the funds to this account.","zh-TW":"請將資金轉入此帳戶。"}]', '{"noun":"transfer, transference","verb":"transfer","adjective":"transferable"}', NULL, 3, 6640, 66),
(6641, 'transfer of ownership', '/ˈtrænsfɜːr əv ˈoʊnərʃɪp/', 'noun', '{"zh-TW":["所有權轉讓"],"en":["the legal process of transferring the title of an asset from one party to another"]}', NULL, 'complete transfer of ownership / transfer of ownership documentation', '[{"en":"The transfer of ownership was finalized at the notary office.","zh-TW":"所有權轉讓在公證處完成了。"},{"en":"A transfer of ownership requires proper documentation and registration.","zh-TW":"所有權轉讓需要適當的文件和登記。"}]', NULL, NULL, 5, 6641, NULL),
(6642, 'transfer pricing', '/ˈtrænsˌfɜːr ˈpraɪsɪŋ/', 'noun', '{"zh-TW":["轉讓定價"],"en":["the price set for transactions between related companies in different countries"]}', NULL, 'transfer pricing policy / transfer pricing audit', '[{"en":"Tax authorities scrutinize transfer pricing between related entities.","zh-TW":"稅務機關仔細審查關聯實體之間的轉讓定價。"},{"en":"The company maintained documented transfer pricing policies for audits.","zh-TW":"公司保存了用於審計的書面轉讓定價政策。"}]', NULL, NULL, 5, 6642, NULL),
(6643, 'transfer student', '/''trænsfɜːr ˌstjuːdənt/', 'noun', '{"zh-TW":["轉學生；轉系生"],"en":["a student who moves from one educational institution to another"]}', NULL, 'support transfer students / welcome transfer students / transfer student application', '[{"en":"Transfer students must meet specific requirements when applying to a new university.","zh-TW":"轉學生在申請新大學時必須滿足特定要求。"},{"en":"The college provides orientation for transfer students to help them adjust.","zh-TW":"大學為轉學生提供迎新活動，幫助他們適應環境。"}]', NULL, NULL, 5, 6643, NULL),
(6644, 'transform', '/trænsˈfɔːrm/', 'verb', '{"zh-TW":["轉變；改造"],"en":["to change completely in form or character"]}', '{"prefix":{"text":"trans-","meaning":"across (跨越)"},"root":{"text":"form","meaning":"shape (形狀)"},"logic":"跨越到另一種形態，即「轉變」。"}', 'transform into / digital transformation; digital transformation / transform the business / transform into', '[{"en":"Technology has transformed the way we work.","zh-TW":"科技改變了我們的工作方式。"},{"en":"The city has been transformed in recent years.","zh-TW":"這座城市近年來已經蛻變。"},{"en":"The company is undergoing a digital transformation.","zh-TW":"公司正在進行數位轉型。"}]', '{"noun":"transformation","adjective":"transformative","verb":"transform"}', NULL, 3, 6644, NULL),
(6645, 'transformative', '/''trænsˌfɔːrmətɪv/', 'adjective', '{"zh-TW":["變革性的；革新的"],"en":["causing a major change in someone''s life, character, or circumstances"]}', NULL, 'transformative experience / transformative change / transformative leadership', '[{"en":"The new CEO''s transformative approach revitalized the struggling company.","zh-TW":"新任首席執行官的變革性方法使這家陷入困境的公司重獲活力。"},{"en":"Digital transformation is having a transformative impact on traditional industries.","zh-TW":"數字化轉型對傳統行業正在產生革命性的影響。"}]', '{"verb":"transform","noun":"transformation"}', NULL, 5, 6645, NULL),
(6646, 'transient', '/''trænziənt/', 'adjective', '{"zh-TW":["短暫的；過渡性的"],"en":["lasting only for a short time; not permanent"]}', NULL, 'transient population / transient nature / transient effect', '[{"en":"The economic boom proved to be transient, lasting only a few years.","zh-TW":"這次經濟繁榮被證明是短暫的，僅持續了幾年。"},{"en":"She sought a transient solution while working on a long-term plan.","zh-TW":"她在制定長期計劃的同時尋求了一個過渡性解決方案。"}]', '{"adverb":"transiently","noun":"transience"}', NULL, 3, 6646, NULL),
(6647, 'transit', '/ˈtrænsɪt/', 'noun', '{"zh-TW":["過境；運輸"],"en":["the process of passing through a place to another destination"]}', NULL, 'in transit / transit passenger', '[{"en":"Passengers in transit do not need to collect their luggage.","zh-TW":"過境旅客不需要提取行李。"},{"en":"The transit lounge is available for connecting passengers.","zh-TW":"轉機旅客可使用過境候機室。"}]', '{"verb":"transit","adjective":"transient"}', NULL, 3, 6647, NULL),
(6648, 'transit lounge', '/''trænsɪt laʊndʒ/', 'noun', '{"zh-TW":["過境休息室；轉機候機廳"],"en":["a lounge at an airport for passengers waiting for a connecting flight"]}', NULL, 'relax in the transit lounge / transit lounge facilities / access the transit lounge', '[{"en":"Transit passengers can access the transit lounge between flights.","zh-TW":"轉機旅客可以在兩次航班之間使用過境休息室。"},{"en":"The airline''s transit lounge offered showers, food, and comfortable seating.","zh-TW":"航空公司的過境休息室提供淋浴、餐食和舒適的座位。"}]', NULL, NULL, 5, 6648, NULL),
(6649, 'transit time', '/''trænsɪt taɪm/', 'noun', '{"zh-TW":["運輸時間；在途時間"],"en":["the time taken for goods to travel from origin to destination"]}', NULL, 'short transit time / transit time estimate / reduce transit time', '[{"en":"The transit time from China to the UK is approximately thirty days by sea.","zh-TW":"從中國到英國的海運運輸時間約為三十天。"},{"en":"Customers chose air freight to reduce transit time for urgent shipments.","zh-TW":"顧客選擇空運以減少緊急貨物的運輸時間。"}]', NULL, NULL, 4, 6649, NULL);